-- Synthetic, independent of Pacote 2.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE TABLE utilizadores(id uuid PRIMARY KEY,empresa_id uuid,funcao text,ativo boolean);
CREATE TABLE colaboradores(id uuid PRIMARY KEY,empresa_id uuid);
CREATE TABLE viaturas(id uuid PRIMARY KEY,empresa_id uuid);
CREATE TABLE ausencias(id uuid PRIMARY KEY,colaborador_id uuid);
CREATE TABLE ausencias_anexos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ausencia_id uuid REFERENCES ausencias(id),arquivo_url text,nome_arquivo text);
CREATE TABLE documentos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL,entidade_tipo text NOT NULL,entidade_id uuid NOT NULL,nome_arquivo text);
CREATE TABLE obras(id uuid PRIMARY KEY,empresa_id uuid);
CREATE TABLE autos_medicao(id uuid PRIMARY KEY,obra_id uuid);
CREATE TABLE faturacao(id uuid PRIMARY KEY,obra_id uuid);
CREATE FUNCTION fn_utilizador_atual_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$;
CREATE FUNCTION fn_e_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM utilizadores WHERE id=fn_utilizador_atual_id() AND ativo AND funcao IN('gerencia','gestao_plataforma')) $$;
CREATE FUNCTION fn_e_administrativo() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT fn_e_admin() OR EXISTS(SELECT 1 FROM utilizadores WHERE id=fn_utilizador_atual_id() AND ativo AND funcao='administrativo') $$;
CREATE FUNCTION fn_pode_ver_obra(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM obras o JOIN utilizadores u ON u.empresa_id=o.empresa_id WHERE o.id=w AND u.id=fn_utilizador_atual_id() AND u.ativo) $$;
CREATE FUNCTION fn_pode_editar_obra(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT fn_pode_ver_obra(w) $$;
CREATE SCHEMA storage;
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text NOT NULL,name text NOT NULL,UNIQUE(bucket_id,name));
CREATE FUNCTION storage.foldername(p text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT (string_to_array(p,'/'))[1:array_length(string_to_array(p,'/'),1)-1] $$;
GRANT USAGE ON SCHEMA public,storage TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON documentos,ausencias_anexos,storage.objects TO authenticated;
GRANT SELECT ON autos_medicao,faturacao TO authenticated;
ALTER TABLE documentos ENABLE ROW LEVEL SECURITY;
ALTER TABLE ausencias_anexos ENABLE ROW LEVEL SECURITY;
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE POLICY ausencias_anexos_rh ON ausencias_anexos FOR ALL TO authenticated USING(fn_e_administrativo()) WITH CHECK(fn_e_administrativo());
CREATE POLICY documentos_rh_storage_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='documentos' AND (storage.foldername(name))[1]='rh' AND (storage.foldername(name))[2] IN('colaborador','viatura') AND fn_e_administrativo());
CREATE POLICY documentos_rh_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='documentos' AND (storage.foldername(name))[1]='rh' AND (storage.foldername(name))[2] IN('colaborador','viatura') AND fn_e_administrativo());
CREATE POLICY documentos_storage_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='documentos' AND CASE WHEN (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' THEN fn_pode_ver_obra(((storage.foldername(name))[1])::uuid) ELSE false END);
CREATE POLICY documentos_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='documentos' AND CASE WHEN (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' THEN fn_pode_editar_obra(((storage.foldername(name))[1])::uuid) ELSE false END);
